class PiratesRules final : public ft::FtRules
{
public:
	void MakeLinks(TPinballTable* table) override;
	void ClearLinks() override;
	void TableControlHandler(MessageCode code) override;
	void BackdoorKey(int key, bool isLeftFlip, bool isRightFlip) override;
	void UnstuckBall(TBall& ball, int dt) override;
	void TextEvent(int ftCode) override;
	const char* GetText(int id) override;
	const char* const* CheatNames(int& count) override;
	void DumpState(std::vector<std::pair<const char*, int>>& out) override;

	pirates::State St;
	// forwarders for the free functions of namespace pirates (the ft::FtRules members are protected)
	void Mission(int code, TPinballComponent* caller) { MissionControl(code, caller); }
	int ScorePartPub(TPinballComponent* c, int i) { return ScorePart(c, i); }
	int ScoreValuePub(TPinballComponent* c, int s) { return ScoreValue(c, s); }
	void SpecialAddScorePub(TPinballComponent* c, int s) { SpecialAddScore(c, s); }
	void AddJackpotPub(int n) { AddJackpot(n); }
	void UnselectPub() { UnselectModeController(); }
	bool InBoundsPub(TBall* b, TPinballComponent* p) { return CheckBallInControlBounds(b, p); }
	void TickerStartPub(bool f) { TickerStart(f); }
	void TickerStopPub() { TickerStop(); }
	void SetModePub(int m) { SetMode(m); }
	int ModePub() const { return Mode(); }
	int& BallSaveRef() { return C.BallSave; }
	TPinballComponent*& LastScorerRef() { return C.LastScorer; }
	int& QuoteFlagRef() { return C.QuoteFlag; }

protected:
	void MissionControl(int code, TPinballComponent* caller) override;
	void SetMode(int m) override;
	int Mode() const override;

private:
	bool Linked = false;
	void MissionControlSwitch(int mode, int code, TPinballComponent* caller);
};
